def is_incomplete(book: dict[str, Any]) -> bool:
    """Promise records need all three core bibliographic fields to be complete."""
    def present(value: Any) -> bool:
        if isinstance(value, str):
            return bool(value.strip()) and value.strip() != '????'
        if isinstance(value, list):
            return bool(value) and any(present(item) for item in value)
        if isinstance(value, dict) and 'name' in value:
            return present(value['name'])
        return bool(value)

    authors = book.get('authors')
    return not (
        present(book.get('title'))
        and present(authors)
        and present(book.get('publish_date'))
    )


